args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT ?p ?o WHERE {
  <http://dbpedia.org/resource/Arthur_Plantagenet,_1st_Viscount_Lisle> ?p ?o .
  FILTER (?p IN (dbp:mother, dbp:father, dbo:parent, dbp:stepmother, dbo:mother, dbo:father))
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?stepmother ?stepmotherLabel WHERE {
  <http://dbpedia.org/resource/Arthur_Plantagenet,_1st_Viscount_Lisle> (dbp:father | dbo:parent) ?father .
  ?father (dbo:spouse | dbp:spouse) ?stepmother .

  OPTIONAL { <http://dbpedia.org/resource/Arthur_Plantagenet,_1st_Viscount_Lisle> dbp:mother ?motherRes . FILTER(isIRI(?motherRes)) }
  OPTIONAL { <http://dbpedia.org/resource/Arthur_Plantagenet,_1st_Viscount_Lisle> dbp:mother ?motherLabel . FILTER(!isIRI(?motherLabel)) }

  OPTIONAL { ?stepmother rdfs:label ?stepmotherLabel . FILTER(lang(?stepmotherLabel) = 'en') }

  FILTER( !(bound(?motherRes) && ?stepmother = ?motherRes) )
  FILTER( !(bound(?motherLabel) && STR(?stepmotherLabel) = STR(?motherLabel)) )
}

